# -*- coding: utf-8 -*-
"""فصل ۵ (رسانه پیام است + گسترش‌های بدن) و فصل ۶ (گرم و سرد + مشارکت ادراکی)."""

def ch5(D):
    D.h1("نظریه‌ی ۱ و ۲: «رسانه پیام است» و گسترش‌های بدن", num="۵")

    D.h2("۵.۱. «رسانه پیام است» — ستون اصلی")
    D.quote("The medium is the message.",
            "معنا: اثرِ بسترِ انتقال (رسانه) بر ساختارِ اجتماع، بسیار بزرگ‌تر از «محتوا» (آنچه در آن جریان دارد) است.",
            cite="مک‌لوهان، 1964 — درک رسانه‌ها (Understanding Media)")
    D.para("این جمله، مشهور‌ترین جمله‌ی مک‌لوهان است و باید سه‌بار، به سه شیوه، خوانده شود:")
    D.bullet("به‌عنوان ضرب‌المثل: رسانه، پیام است — یعنی «چیز» اهمیت دارد، نه «آنچه در آن می‌رود».")
    D.bullet("به‌عنوان تعریف: پیام اصلی یک رسانه، تغییر در مقیاس/آهنگ/الگوی روابط انسانی‌ای است که آن رسانه ایجاد می‌کند — نه محتوای انتقال‌داده‌شده.")
    D.bullet("به‌عنوان انتقاد: منتقدان می‌گویند این جمله، «محتوا» را به‌طور کامل نادیده می‌گیرد و «رسانه» را به‌شکل جادویی درمی‌آورد.")

    D.h3("۵.۱.۱. مثالِ لامپ برقی")
    D.para("مک‌لوهان بارها مثالِ «لامپ برقی» را به‌کار برد: لامپ، «رسانه‌ای بدون محتوا» است — هیچ پیامی را انتقال نمی‌دهد. اما با صرفِ حضورش، «محیط» می‌سازد: شب را روز می‌کند، کار را گسترش می‌دهد، الگوی زندگی را تغییر می‌دهد. پیامِ لامپ، «نور» نیست؛ پیامش، «تغییری در الگوی زندگی انسانی» است. همین مثال، کلید فهم شعار اوست.")

    D.h3("۵.۱.۲. «محتوای هر رسانه، همیشه رسانه‌ی دیگری است»")
    D.para("این جمله‌ی مکمل، نیمی دیگر از معمای «رسانه پیام است» است: محتوایِ هر رسانه، خودِ یک رسانه‌ی دیگر است. مثلاً: محتوایِ «گفتار» (speech)، «خودِ فکر/تجربه» است؛ محتوایِ «نوشتار» (writing)، «گفتار» است؛ محتوایِ «چاپ» (print)، «نوشتار» است؛ محتوایِ «تلویزیون»، «چاپ» و «گفتار» است. این زنجیره، نشان می‌دهد که «محتوا» و «رسانه» دو سطح از یک ساختارند، نه دو چیز جدا.")

    D.h3("۵.۱.۳. پاسخ به سؤالی‌ای که هر کسی می‌پرسد: «محتوا اصلاً بی‌اثر است؟»")
    D.para("در مصاحبه‌ی Playboy (1969)، از مک‌لوهان پرسیدند: «اگر رسانه پیام است، پس چرا محتوای سخنرانی‌های رادیویی هیتلر بر آلمان‌ها اثر نداشت؟» مک‌لوهان پاسخ داد: «من نمی‌گویم محتوا بی‌اثر است؛ می‌گویم نقشِ آن، «ذیل» (subordinate) است. حتی اگر هیتلر درس‌های گیاه‌شناسی می‌خواند، یک دیکتاتورِ دیگر از رادیو استفاده می‌کرد تا آلمان‌ها را «تبریزالیزه» کند. رادیو، به‌عنوان رسانه، «مشارکت ادراکیِ تجمعی» ایجاد می‌کرد — و این مشارکت، زمینه‌ساز فاشیسم شد.» این پاسخ، ظرافتِ تفکر مک‌لوهان را نشان می‌دهد: او محتوا را انکار نمی‌کرد، بلکه آن را «در خدمتِ رسانه» قرار می‌داد.")

    D.h2("۵.۲. گسترش‌های بدن (Extensions of Man)")
    D.quote("Every medium is an extension of some faculty of physical man.",
            "معنا: هر رسانه، گسترشی از یکی از اندام‌ها/حس‌های جسمانی انسان است.",
            cite="مک‌لوهان، درک رسانه‌ها، 1964")
    D.para("این مفهوم، «ریشه‌ی انسان‌شناختی» شعار «رسانه پیام است» است. مک‌لوهان معتقد بود فناوری‌ها، «گسترش» اندام‌های انسان‌اند:")
    D.bullet("چرخ = گسترشِ پا (پهلو)")
    D.bullet("لباس = گسترشِ پوست")
    D.bullet("برق = گسترشِ سیستم عصبی")
    D.bullet("خط نوشتاری = گسترشِ صدا/گفتار")
    D.bullet("تلویزیون = گسترشِ سیستم عصبی مرکزی (CNS) در مقیاس جمعی")
    D.para("اما نکته‌ی کلیدی اینجاست: «گسترش» همیشه به «جایگزینی» منجر می‌شود. وقتی پا را با چرخ گسترش می‌دهیم، پا «منسوخ» (obsoleted) می‌شود — دیگر به‌همان اندازه استفاده نمی‌شود. وقتی سیستم عصبی را با برق گسترش می‌دهیم، «حس لامسه» (haptic) در مقابل «حس بصری» (optical) کم‌رنگ می‌شود. این فرایند «بهبود/منسوخ‌سازی» (enhance/obsolete)، ریشه‌ی «تتراد» است (فصل ۸).")
    D.callout("تمرین ۵:", "گوشی هوشمند را به‌عنوان «گسترش بدن» تحلیل کنید. کدام اندام/حس را گسترش می‌دهد؟ کدام حس را «منسوخ» می‌کند؟ (پاسخ پیشنهادی: گوشی، هم‌زمان گسترشِ چشم، گوش، دست و «حافظه» است؛ و «حس فاصله» و «زمان‌بندی طبیعی» را منسوخ می‌کند.)")

    D.h2("۵.۳. «رسانه ماساژ است» (The Medium Is the Massage) — بسط مفهوم")
    D.para("در کتاب رسانه ماساژ است (1967، با کوینتین فیور)، مک‌لوهان مفهوم «رسانه پیام است» را بسط داد: رسانه، «پیام» نیست، بلکه «ماساژ» (massage) کلِ محیط انسانی است. این «ماساژ»، «نامرئی» و «بناکننده‌ی» (constructive) است — همان‌طور که «لامپ برقی» «محتوا» ندارد اما «محیط» می‌سازد، رسانه‌ها «ماساژ» می‌دهند: «حس‌ها را تنظیم می‌کنند، الگوهای ادراک را تغییر می‌دهند، و ساختار اجتماعی را باز می‌سازند.» بازی با کلمه‌ی «Massage/Message/Mass Age»، خود نمادی‌ای از «رسانه‌ای‌بودن» سبک مک‌لوهان است: «شکل» (mass) و «محتوا» (massage/message) در یک کلمه ادغام می‌شوند.")

    D.h2("۵.۴. رسانه به‌عنوان «بازیگوشی» و «آینه»")
    D.para("مک‌لوهان بارها تأکید کرد که رسانه، «آینه‌ای» است که «خودِ ما» را به ما نشان می‌دهد: «هر رسانه، یک آینه‌ی بزرگ‌تر از طبیعت (larger-than-nature) است که خودِ ما را به ما می‌رساند.» این «آینه‌سازی»، «رسانه پیام است» را از یک «جمله‌ی انتزاعی» به یک «ابزارِ عملی» تبدیل می‌کند: وقتی «تصویر خودمان» را در یک رسانه می‌بینیم، در واقع «ساختار اجتماعی‌ای» را می‌بینیم که آن رسانه می‌سازد. این «آینه‌سازی»، در تحلیل «شبکه‌های اجتماعی» به‌ویژه کاربردی است: «خودِ ما» که در اینستاگرام می‌بینیم، «ساختاری‌ای» است که اینستاگرام می‌سازد، نه «خودِ واقعی» ما.")
    D.page_break()


def ch6(D):
    D.h1("نظریه‌ی ۳ و ۴: رسانه‌های گرم و سرد + مشارکت ادراکی", num="۶")

    D.h2("۶.۱. رسانه‌های گرم و سرد (Hot and Cool Media)")
    D.quote("A hot medium excludes and a cool medium includes; hot media are low in participation, cool media are high in participation.",
            "معنا: رسانه‌ی گرم، «بازدارنده» و «مشارکت‌پایین» است؛ رسانه‌ی سرد، «شامل‌کننده» و «مشارکت‌بالا» است.",
            cite="مصاحبه‌ی Playboy، 1969")
    D.para("این مفهوم، یکی از بحث‌برانگیزترین و در عین حال کاربردی‌ترین تمایزهای مک‌لوهان است. تعریف دقیق:")
    D.bullet("رسانه‌ی گرم (hot): یک حس را با «جزئیات زیاد» (high definition) امتداد می‌دهد و برای تکمیلِ ادراکی، «مشارکتِ کمتری» از مخاطب می‌طلبد. مثال‌ها: رادیو (صدا با جزئیات زیاد)، فیلم سینمایی (تصویر با جزئیات زیاد)، عکس (اطلاعات بصری زیاد).")
    D.bullet("رسانه‌ی سرد (cool): یک حس را با «جزئیات کم» (low definition) امتداد می‌دهد و «مشارکتِ بیشتری» از مخاطب می‌طلبد. مثال‌ها: تلویزیون (در دوران مک‌لوهان، کم‌وضوح)، تلفن (صدا محدود)، گفت‌وگو و سیمینار.")

    D.h3("۶.۱.۱. نکته‌ی کلیدی: «مشارکت» یعنی «تکمیلِ ادراکی»")
    D.para("بسیاری از مخاطبان، «مشارکت» را به‌معنای «کلیک کردن، کامنت گذاشتن، یا درگیر شدن ذهنی عمیق» می‌فهمند. اما در ادبیات مک‌لوهان، «مشارکت» به‌معنای «تکمیلِ ادراکی» (perceptual completion) است: پرکردنِ آنچه رسانه ارائه نداده. وقتی یک عکسِ کم‌وضوح می‌بینید، مغز شما «با کمکِ نشانه‌ها، تجربه و بافت»، تصویر را کامل می‌کند — این، «مشارکت ادراکی» است. رسانه‌ی سرد، چون «جزئیات کمتری» ارائه می‌دهد، «سهمِ بیشتری» از مخاطب در تکمیل می‌طلبد.")

    D.h3("۶.۱.۲. چرا تلویزیون «سرد» است؟ (و چرا رادیو «گرم»؟)")
    D.para("مک‌لوهان، تلویزیونِ دهه‌ی ۱۹۵۰ و ۶۰ را «سرد» می‌دانست، چون تصویرش کم‌وضوح بود و مخاطب باید «بیشتر تکمیل» می‌کرد. در مقابل، رادیو را «گرم» می‌دانست، چون صدا «جزئیات زیاد» داشت و مخاطب «کمتر تکمیل» می‌کرد. ادیت افرون (Edith Ehren?) تلویزیون را «غول خجالتی» (shy giant) خواند — رسانه‌ای‌ای که «کمتر می‌گوید، اما بیشتر درگیر می‌کند.» (نکته: انتساب «غول خجالتی» به ادیت افرون، در فصل درک رسانه‌ها آمده است.)")

    D.h3("۶.۱.۳. چالش‌ها و بازخوانی‌ها")
    D.para("تمایز گرم/سرد، از ابتدا مورد انتقاد قرار گرفت. منتقدان می‌گویند: «تعریفِ بالا/پایین» (high/low definition) مبهم است و معیارِ سنجش ندارد. در فصل ۱۱ (نقدها) با جزئیات به این انتقادها می‌پردازیم. اما در عین حال، این تمایز، ابزاری‌ای شد که در تحلیل رسانه‌های معاصر (از پادکست تا ویدیوهای کوتاه) به‌کار می‌رود. مقاله‌ی Hoffert (2016) در این مجموعه، «پایه‌ی علمی» برای تمایز گرم/سرد ارائه می‌دهد.")

    D.h2("۶.۲. مشارکت ادراکی: سهم مخاطب در تکمیل پیام")
    D.para("مشارکت ادراکی، «روان‌شناختی»ِ تمایز گرم/سرد است. وقتی رسانه «همه‌چیز» را ارائه نمی‌دهد، مخاطب با کمکِ نشانه‌ها، تجربه و بافت، پیام را «ساخت» می‌کند. این «ساخت»، خود نوعی «خلاقیت ادراکی» است:")
    D.bullet("یک عکسِ پُرجزئیات: چشم‌ها، پوست، سایه‌ها مشخص است؛ رسانه «بیشتر» ارائه داده و سهم شما از تکمیل «کمتر» است.")
    D.bullet("یک طرح کارتونی ساده: چند خط و نقطه را «چهره» تشخیص می‌دهید — با «نشانه‌های کمتر»، صورتی معنادار می‌سازید. سهم شما در دریافت، «بیشتر» است.")

    D.h3("۶.۲.۱. سه سطح «درگیری» مخاطب (برای تفکیک از مشارکت ادراکی)")
    D.table(
        headers=["سطح", "سؤال کلیدی", "مثال"],
        rows=[
            ["تکمیل ادراکی", "این تصویر/صدا را چگونه «دریافت» و «تشخیص» می‌دهم؟", "تشخیص چهره در یک طرح ساده"],
            ["تفسیر", "این پیام «چه معنایی» دارد؟", "درک نمادها و استعاره‌ها در یک فیلم"],
            ["تفکر انتقادی", "آیا «ادعای» آن معتبر است و «چه شواهدی» دارد؟", "سنجش منابع یک خبر در شبکه‌های اجتماعی"],
        ],
        col_widths=[4, 7, 5],
    )
    D.para("مهم: «مشارکت ادراکی» در ادبیات مک‌لوهان، به‌معنای «سطح اول» است — نه «تفکر انتقادی» (سطح سوم). اگر از مخاطبِ یک رسانه‌ی گرم «مشارکت» بخواهید، منظور «تکمیلِ ادراکی» است، نه «بررسی‌ی انتقادیِ منابع». این تفکیک، برای درک درستِ نظریه ضروری است.")
    D.callout("تمرین ۶:", "دو رسانه‌ی معاصر را (مثلا‌ً «یوتیوب» و «پادکست») در چارچوب گرم/سرد و مشارکت ادراکی تحلیل کنید. کدام «جزئیات بیشتری» ارائه می‌دهد؟ مخاطب در کدام «بیشتر تکمیل» می‌کند؟")
    D.page_break()
